import pandas as pd

def clean(df):
    df = df.copy()
    # Price is text; strip '$' prefixes and convert to numeric
    df['Price'] = df['Price'].astype(str).str.replace('$', '', regex=False).str.strip().astype(float)
    return df

def answer(df):
    result = {}
    grouped = df.groupby('Category')['Price'].mean()
    for category, value in grouped.items():
        if pd.notna(category):
            result[category] = round(float(value), 2)
    return result
